export const AQ_PREVIEW="<!doctype html>\n<html lang=\"pt-BR\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#0c181c\"><title>Aquário do Betta · Agenda Personal</title>\n<style>\n:root{color-scheme:dark;font-family:system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;color:#f0f3ed;background:#0c1519;font-synthesis:none;--accent:#b3e65a}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 50% 12%,#17383c55,transparent 65%),#0c1519}button,a{-webkit-tap-highlight-color:transparent}button{font:inherit;cursor:pointer}button:focus-visible,a:focus-visible{outline:2px solid var(--accent);outline-offset:4px}.shell{max-width:1000px;margin:0 auto;padding:26px 30px 32px}.brand{font-size:12px;font-weight:700;letter-spacing:.16em;color:#b9c7c1;display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:29px}.brand span{letter-spacing:.02em;font-size:11px;font-weight:400;color:#a7bcb5;border:1px solid #42524e;border-radius:20px;padding:5px 10px}h1{font-size:clamp(25px,3.5vw,36px);font-weight:650;letter-spacing:-.04em;margin:0 0 8px}.intro{color:#b1c0bb;line-height:1.55;font-size:15px;margin:0 0 21px}.tank{-webkit-tap-highlight-color:transparent;aspect-ratio:1.55;min-height:300px;border-radius:24px;border:1px solid #6b85775c;box-shadow:0 12px 45px #0003;position:relative;overflow:hidden;background:#0b3640;--mascot-accent:var(--accent);cursor:pointer}.tank:focus-visible{outline:2px solid var(--accent);outline-offset:5px}.cue{position:absolute;bottom:17px;left:18px;z-index:3;margin:0;pointer-events:none;font-size:12px;color:#f0f7f1;text-shadow:0 1px 4px #001617;background:#04222c77;padding:8px 12px;border:1px solid #aac8b530;border-radius:10px;backdrop-filter:blur(7px)}.controls{display:flex;align-items:flex-end;justify-content:space-between;gap:22px;padding:23px 0 21px;border-bottom:1px solid #a7b9ad29}.group-label{font-size:11px;letter-spacing:.1em;text-transform:uppercase;font-weight:650;color:#91a69d;display:block;margin:0 0 9px}.seg{display:flex;gap:4px;background:#16262a;border:1px solid #576d5f40;border-radius:12px;padding:4px}.seg button{background:none;color:#c4d1cb;border:0;padding:10px 13px;font-size:13px;border-radius:8px;min-height:40px}.seg button[aria-pressed=true]{background:#31423c;color:#eff8df;box-shadow:inset 0 0 0 1px #91b75055}.colors{display:flex;gap:9px}.colors button{border:1px solid #4b645a;background:#15262b;border-radius:50%;width:42px;height:42px;display:grid;place-items:center}.colors button::after{content:\"\";display:block;width:23px;height:23px;border-radius:50%;background:var(--swatch);box-shadow:inset 0 0 0 1px #ffffff45}.colors button[aria-pressed=true]{border:2px solid var(--accent);box-shadow:0 0 0 3px #b3e65a13}.call{border:1px solid #b3e65a80;border-radius:11px;padding:13px 17px;min-height:46px;background:#233b32;color:#e6f5c9;font-size:13px;font-weight:600}.scenery{margin-top:22px}.scenes{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:11px}.scene{display:block;min-width:0;text-align:left;border:1px solid #42574c;background:#15272b;border-radius:12px;padding:4px;color:#c7d3cc;overflow:hidden}.scene[aria-pressed=true]{border-color:var(--accent);background:#253c32;color:#eef6df}.scene .thumb{display:block;height:68px;border-radius:8px;background:#103943;background-size:cover;background-position:center}.scene strong{display:block;font-size:11px;font-weight:550;line-height:1.3;padding:8px 5px 5px}.foot{margin:21px 0 0;display:flex;gap:12px;justify-content:space-between;align-items:baseline;font-size:11px;color:#8fa69b;line-height:1.6}.foot p{margin:0;max-width:610px}.foot a{color:#c6dba8;white-space:nowrap;text-underline-offset:3px}#mediaStatus{font-size:11px;color:#92aaa0;margin:16px 0 0;min-height:18px}body.phone .shell{max-width:400px;padding:23px 15px}body.phone .tank{aspect-ratio:1.25;border-radius:18px}body.phone .controls{flex-wrap:wrap;gap:18px 10px}body.phone .seg button{padding:9px 10px}body.phone .scenes{grid-template-columns:repeat(3,minmax(0,1fr))}body.phone .foot{display:block}body.phone .foot a{display:inline-block;margin-top:12px}body.phone .brand{margin-bottom:24px}body.phone .cue{font-size:10px;left:10px;bottom:11px;padding:7px 9px}\n@media(max-width:620px){.shell{padding:23px 15px}.brand{margin-bottom:24px}.tank{aspect-ratio:1.25;border-radius:18px}.controls{flex-wrap:wrap;gap:18px 10px}.seg button{padding:9px 10px}.scenes{grid-template-columns:repeat(3,minmax(0,1fr))}.scene .thumb{height:65px}.foot{display:block}.foot a{display:inline-block;margin-top:12px}.cue{font-size:10px;left:10px;bottom:11px;padding:7px 9px}}\n@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}\n</style></head><body><main class=\"shell\"><div class=\"brand\">AGENDA PERSONAL <span>Prévia interativa</span></div><h1>Aquário do Betta</h1><p class=\"intro\">Toque no vidro para chamar seu companheiro para perto.</p><div class=\"tank\" id=\"tank\" role=\"button\" tabindex=\"0\" aria-label=\"Tocar no vidro e chamar o peixe\"><p class=\"cue\">Um toque no vidro, e ele vem até você.</p></div><div class=\"controls\"><div><span class=\"group-label\">Fase</span><div class=\"seg\" aria-label=\"Fase do peixe\"><button data-phase=\"baby\" aria-pressed=\"false\">Filhote</button><button data-phase=\"teen\" aria-pressed=\"false\">Adolescente</button><button data-phase=\"adult\" aria-pressed=\"true\">Adulto</button></div></div><div><span class=\"group-label\">Cor</span><div class=\"colors\" aria-label=\"Cor do peixe\"><button data-color=\"original\" style=\"--swatch:linear-gradient(135deg,#e54237 50%,#f1e4e3 50%)\" aria-label=\"Vermelho e branco\" aria-pressed=\"true\"></button><button data-color=\"blue\" style=\"--swatch:linear-gradient(135deg,#2d86cb 50%,#e1e9f0 50%)\" aria-label=\"Azul e branco\" aria-pressed=\"false\"></button><button data-color=\"gold\" style=\"--swatch:linear-gradient(135deg,#e8ab32 50%,#252d35 50%)\" aria-label=\"Dourado e preto\" aria-pressed=\"false\"></button></div></div><button class=\"call\" id=\"call\">Chamar peixe</button></div><div class=\"scenery\"><span class=\"group-label\">Cenário</span><div class=\"scenes\" id=\"scenes\"></div></div><p id=\"mediaStatus\" role=\"status\" aria-live=\"polite\"></p><footer class=\"foot\"><p>Esta prévia permite experimentar as fases, cores e cenários. As escolhas aqui não alteram XP, compras ou progresso no aplicativo.</p><a href=\"/api/aquarium/v1/media.json\" download=\"AgendaPersonal-Aquario-1.aquarium.json\">Baixar imagens do aquário</a></footer></main>\n<script src=\"/api/aquarium/v1/runtime.js?v=betta-1.1\"></script><script>\n(function(){'use strict';if(new URLSearchParams(location.search).get('phone')==='1')document.body.classList.add('phone');\nconst state={species:'fish',name:'Betta',xp:1800,colors:{fish:'original'},aquariumHome:'aq-jardim',equipped:{home:'aq-jardim'}},tank=document.getElementById('tank'),status=document.getElementById('mediaStatus'),scenes=[['jardim','Jardim submerso'],['ruinas','Ruínas submersas'],['cristais','Gruta de cristais'],['cachoeira','Cachoeira submersa'],['naufragio','Naufrágio']];\nglobalThis.APMascotModel={phase:xp=>({id:xp>=1800?'adult':xp>=600?'teen':'baby'}),color:s=>({id:s.colors.fish}),pose:()=>({id:'default'})};\ndocument.getElementById('scenes').innerHTML=scenes.map(([id,name])=>'<button class=\"scene\" data-scene=\"aq-'+id+'\" aria-pressed=\"'+(id==='jardim')+'\"><span class=\"thumb\"></span><strong>'+name+'</strong></button>').join('');\nfunction draw(){APAquarium.decorate(tank,state);for(const b of document.querySelectorAll('[data-phase]'))b.setAttribute('aria-pressed',String(b.dataset.phase===APMascotModel.phase(state.xp).id));for(const b of document.querySelectorAll('[data-color]'))b.setAttribute('aria-pressed',String(b.dataset.color===state.colors.fish));for(const b of document.querySelectorAll('[data-scene]')){b.setAttribute('aria-pressed',String(b.dataset.scene===state.aquariumHome));const img=APAquarium.scene(b.dataset.scene);if(img)b.querySelector('.thumb').style.backgroundImage='url(\"'+img+'\")'}status.textContent=APFishMedia.ready()?'Imagens do aquário salvas neste aparelho.':APFishMedia.status().error||'Carregando as imagens do seu aquário…'}\nfor(const b of document.querySelectorAll('[data-phase]'))b.addEventListener('click',()=>{state.xp={baby:0,teen:600,adult:1800}[b.dataset.phase];draw()});for(const b of document.querySelectorAll('[data-color]'))b.addEventListener('click',()=>{state.colors.fish=b.dataset.color;draw()});for(const b of document.querySelectorAll('[data-scene]'))b.addEventListener('click',()=>{state.aquariumHome=b.dataset.scene;state.equipped.home=b.dataset.scene;draw()});document.getElementById('call').addEventListener('click',()=>APAquarium.tap(tank,.5,.57));tank.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();APAquarium.tap(tank,.5,.57)}});addEventListener('ap-aquarium-media',()=>{if(APFishMedia.ready())draw();else status.textContent=APFishMedia.status().error||'Carregando as imagens do seu aquário…'});\nAPFishMedia.init({...__AP_AQUARIUM_CONFIG__,url:new URL('/api/aquarium/v1/media.json',location.href).href}).then(draw);draw();\n})();</script></body></html>\n";
